def to_metadata(
    self,
    metadata,
    schema=RETAIN_SCHEMA,
    referred_schema_fn=None,
    name=None,
):
    if name is None:
        name = self.name
    if schema is RETAIN_SCHEMA:
        schema = self.schema
    elif schema is None:
        schema = metadata.schema
    key = _get_table_key(name, schema)
    if key in metadata.tables:
        util.warn(
            "Table '%s' already exists within the given "
            "MetaData - not copying." % self.description
        )
        return metadata.tables[key]

    args = []
    for col in self.columns:
        args.append(col._copy(schema=schema))
    table = Table(
        name,
        metadata,
        schema=schema,
        comment=self.comment,
        *args,
        **self.kwargs,
    )
    for const in self.constraints:
        if isinstance(const, ForeignKeyConstraint):
            referred_schema = const._referred_schema
            if referred_schema_fn:
                fk_constraint_schema = referred_schema_fn(
                    self, schema, const, referred_schema
                )
            else:
                fk_constraint_schema = (
                    schema if referred_schema == self.schema else None
                )
            table.append_constraint(
                const._copy(
                    schema=fk_constraint_schema, target_table=table
                )
            )
        elif not const._type_bound:
            # skip unique constraints that would be generated
            # by the 'unique' flag on Column
            if const._column_flag:
                continue

            table.append_constraint(
                const._copy(schema=schema, target_table=table)
            )
    for index in self.indexes:
        # skip indexes that would be generated
        # by the 'index' flag on Column
        if index._column_flag:
            continue
        Index(
            index.name,
            unique=index.unique,
            *[
                _copy_expression(expr, self, table)
                for expr in index.expressions
            ],
